// SPDX-License-Identifier: LGPL-3.0-only
//! The Windows text behaviour that follows from the font's own tables, against real Qt 6.12
//! (`tests/data/directwrite_gaps_golden.txt`, regenerated by
//! `tests/data/gen_directwrite_gaps_golden.py`):
//!
//! * which source kerns a run: Tahoma has a GPOS `kern` feature for Arabic only, so Qt (HarfBuzz
//!   14.5, `hb_ot_shape_planner_t::compile`) kerns its Latin, Cyrillic, Greek, Hebrew and Thai
//!   text from the `kern` table, which needs the script of the run (Qt's script items,
//!   `QUnicodeTools::initScripts`) and applies at a device pixel ratio other than 1;
//! * the line metrics of fonts with embedded bitmaps (MS Gothic, SimSun, MingLiU, Calibri), which
//!   Qt keeps from DirectWrite (`QFontEngine::initializeHeightMetrics`) instead of reading the
//!   font's tables and rounding.
//!
//! The system fonts are compared only when the file on this machine is the one the golden was
//! measured with (size and hash in the golden), so another Windows build skips them instead of
//! failing. The ratio is process-wide state: the tests take turns.
#![cfg(windows)]

use ferrokit_gui::geometry::primitives::PointF;
use ferrokit_gui::paint::{Painter, Pen, Pixmap};
use ferrokit_gui::text::directwrite_face::is_available;
use ferrokit_gui::text::font::{Font, FontStyle, FontWeight};
use ferrokit_gui::text::font_database::set_application_device_pixel_ratio;
use ferrokit_gui::text::font_metrics::FontMetrics;
use ferrokit_gui::text::smoothing::TextSmoothing;
use ferrokit_gui::tiny_skia::Color;
use std::sync::Mutex;

const GOLDEN: &str = include_str!("data/directwrite_gaps_golden.txt");

/// The ratio and the font database are process-wide.
static LOCK: Mutex<()> = Mutex::new(());

fn fnv1a64(data: &[u8]) -> u64 {
    data.iter().fold(0xcbf2_9ce4_8422_2325u64, |h, &b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)
    })
}

fn text(id: &str) -> &'static str {
    match id {
        "k" => "AVAWTo.,:;AaVyTa",
        "l" => "iiiiiIIIlll WWWMMM",
        "m" => "Claude Code 42% resets in 2h 13m",
        "n" => "The quick brown fox jumps over the lazy dog",
        "o" => "To\u{200d}AV A\u{200c}V Te\u{200b}Ty",
        "p" => {
            "AV \u{5e9}\u{5dc}\u{5d5}\u{5dd} AV \u{645}\u{631}\u{62d}\u{628}\u{627} To \u{e2a}\u{e27}\u{e31}\u{e2a}\u{e14}\u{e35}"
        }
        "q" => "\u{41f}\u{440}\u{438}\u{432}\u{435}\u{442} AVA \u{391}\u{392}\u{393} To",
        other => panic!("no text {other}"),
    }
}

fn font_of(family: &str, weight: u32, italic: bool, px: u32) -> Font {
    let mut font = Font::new(family, px as f32);
    font = font.with_weight(if weight >= 600 {
        FontWeight::Bold
    } else {
        FontWeight::Normal
    });
    if italic {
        font = font.with_style(FontStyle::Italic);
    }
    font
}

/// `QFontMetricsF::horizontalAdvance` in 1/64 px.
fn advance64(font: &Font, text: &str) -> i64 {
    let advance = FontMetrics::from_font(font).horizontal_advance_exact(text, font);
    let fixed = f64::from(advance) * 64.0;
    assert_eq!(
        fixed,
        fixed.round(),
        "{text:?} is not a whole number of 1/64 px"
    );
    fixed as i64
}

/// A 26.6 pixel value as the whole 1/64 px it is.
fn fixed64(value: f32) -> i64 {
    let fixed = f64::from(value) * 64.0;
    assert_eq!(
        fixed,
        fixed.round(),
        "{value} is not a whole number of 1/64 px"
    );
    fixed as i64
}

/// `QPainter::drawText` of `text` with a black pen on white, ClearType, as the golden's.
fn draw(font: &Font, px: u32, text: &str, dpr: f32) -> (u32, u32, u64) {
    let (w, h) = (360.0 * dpr, ((px * 2 + 15) / 4 * 4) as f32 * dpr);
    let mut pixmap =
        Pixmap::with_dpr(w.round() as u32, h.round() as u32, dpr).expect("pixmap of a golden case");
    pixmap.fill(Color::from_rgba8(255, 255, 255, 255));
    {
        let mut painter = Painter::begin(&mut pixmap);
        painter.set_text_smoothing(TextSmoothing {
            cleartype: true,
            gamma: 1.2,
        });
        painter.set_pen(Some(Pen::new(Color::from_rgba8(0, 0, 0, 255), 1.0)));
        painter.draw_text(PointF::new(6.0, px as f32 + 6.0), text, font);
    }
    (
        pixmap.physical_width(),
        pixmap.physical_height(),
        fnv1a64(pixmap.data()),
    )
}

fn hex(field: &str) -> u64 {
    u64::from_str_radix(field, 16).expect("hash")
}

/// Compares one golden line of `kind` (`kern` or `met`); `Err` carries the report of a difference.
fn compare(
    kind: &str,
    family: &str,
    font: &Font,
    px: u32,
    dpr: f32,
    rest: &[&str],
) -> Result<(), String> {
    let label = format!("{kind} {family} {px} px x{dpr} {}", rest.join(" "));
    let (got, want) = match (kind, rest[0]) {
        ("kern", "adv") => (
            format!("{}/64", advance64(font, text(rest[1]))),
            format!("{}/64", rest[2]),
        ),
        ("kern", "draw") => {
            let (w, h, hash) = draw(font, px, text(rest[1]), dpr);
            (
                format!("{w}x{h} {hash:016x}"),
                format!("{}x{} {:016x}", rest[2], rest[3], hex(rest[4])),
            )
        }
        ("met", _) => {
            let metrics = FontMetrics::from_font(font);
            let engine = FontMetrics::engine_metrics(font).expect("an installed font has metrics");
            (
                format!(
                    "{} {} {} {} {} {}",
                    metrics.ascent,
                    metrics.descent,
                    metrics.line_gap,
                    fixed64(engine.ascent),
                    fixed64(engine.descent),
                    fixed64(engine.leading)
                ),
                rest.join(" "),
            )
        }
        other => panic!("golden line {other:?}"),
    };
    (got == want)
        .then_some(())
        .ok_or(format!("{label}: {got}, Qt {want}"))
}

/// Runs the golden lines of `kind` whose font file is on this machine unchanged. Returns
/// (compared, failures).
fn run_golden(kind: &str) -> (usize, Vec<String>) {
    let mut compared = 0;
    let mut failures = Vec::new();
    let mut installed = false;
    for line in GOLDEN
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
    {
        let fields: Vec<&str> = line.split(' ').collect();
        if fields[0] == "sysfont" {
            let (size, hash) = (fields[2].parse::<usize>().unwrap(), hex(fields[3]));
            let dir = std::env::var("WINDIR").unwrap_or_else(|_| "C:/Windows".to_string());
            installed = std::fs::read(format!("{dir}/Fonts/{}", fields[1]))
                .ok()
                .is_some_and(|bytes| bytes.len() == size && fnv1a64(&bytes) == hash);
            if !installed {
                eprintln!("skipping {}: not installed as measured", fields[1]);
            }
            continue;
        }
        if fields[0] != kind || !installed {
            continue;
        }
        // `<kind> <dpr> <family> <weight> <italic> <px> ...`
        let dpr: f32 = fields[1].parse().expect("dpr");
        let family = fields[2].replace('_', " ");
        let weight: u32 = fields[3].parse().expect("weight");
        let italic = fields[4] == "1";
        let px: u32 = fields[5].parse().expect("size");
        set_application_device_pixel_ratio(dpr);
        let font = font_of(&family, weight, italic, px);
        compared += 1;
        if let Err(report) = compare(kind, &family, &font, px, dpr, &fields[6..]) {
            failures.push(report);
        }
    }
    set_application_device_pixel_ratio(1.0);
    (compared, failures)
}

fn assert_identical(kind: &str) {
    if !is_available() {
        return;
    }
    let _turn = LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let (compared, failures) = run_golden(kind);
    assert!(
        failures.is_empty(),
        "{} of {compared} differ from Qt:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn tahoma_is_kerned_from_its_kern_table_per_script_like_qt() {
    assert_identical("kern");
}

#[test]
fn fonts_with_embedded_bitmaps_keep_directwrites_line_metrics_like_qt() {
    assert_identical("met");
}
